package com.witchersbestiary.enchantment;
import java.util.Properties;
/** Restart-loaded server balance in the existing properties file; never supplied by a client. */
public final class EnchantmentSettings {
 public static final String DEFAULTS="\nenchantments.monstersBane1=0.05\nenchantments.monstersBane2=0.09\nenchantments.monstersBane3=0.13\nenchantments.frostTicks1=30\nenchantments.frostTicks2=50\nenchantments.frostTicks3=50\nenchantments.frostCooldown=60\nenchantments.bloodHeal1=0.5\nenchantments.bloodHeal2=1.0\nenchantments.bloodHeal3=1.5\nenchantments.bloodCooldown=60\nenchantments.runicHits1=5\nenchantments.runicHits2=4\nenchantments.runicHits3=3\nenchantments.runicRadius1=2.0\nenchantments.runicRadius2=2.5\nenchantments.runicRadius3=3.0\nenchantments.runicDamage=2.0\nenchantments.runicCooldown=80\nenchantments.runicMaxTargets=8\n";
 private final double[] bane=new double[3],heal=new double[3],radius=new double[3];private final int[] frost=new int[3],hits=new int[3];
 public final int bloodCooldown,frostCooldown,runicCooldown,maxTargets;public final float pulseDamage;
 public EnchantmentSettings(Properties p){for(int i=0;i<3;i++){bane[i]=read(p,"monstersBane"+(i+1),new double[]{.05,.09,.13}[i],0,.15);heal[i]=read(p,"bloodHeal"+(i+1),new double[]{.5,1,1.5}[i],0,2);radius[i]=read(p,"runicRadius"+(i+1),2+i*.5,1,4);frost[i]=(int)read(p,"frostTicks"+(i+1),i==0?30:50,10,80);hits[i]=(int)read(p,"runicHits"+(i+1),5-i,2,8);}bloodCooldown=(int)read(p,"bloodCooldown",60,40,1200);frostCooldown=Math.max(java.util.Arrays.stream(frost).max().orElse(50)+10,(int)read(p,"frostCooldown",60,20,1200));runicCooldown=(int)read(p,"runicCooldown",80,60,1200);maxTargets=(int)read(p,"runicMaxTargets",8,1,12);pulseDamage=(float)read(p,"runicDamage",2,0,4);}
 private static double read(Properties p,String key,double fallback,double min,double max){try{double n=Double.parseDouble(p.getProperty("enchantments."+key,""+fallback));return Double.isFinite(n)?Math.clamp(n,min,max):fallback;}catch(NumberFormatException invalid){return fallback;}}
 public double bane(int level){return bane[Math.clamp(level,1,3)-1];}public float heal(int level){return (float)heal[Math.clamp(level,1,3)-1];}public double radius(int level){return radius[Math.clamp(level,1,3)-1];}public int frost(int level){return frost[Math.clamp(level,1,3)-1];}public int hits(int level){return hits[Math.clamp(level,1,3)-1];}
}
